from datetime import datetime, timezone, timedelta

class Time(datetime):
    def __init__(self, microseconds=0, nanoseconds=0, tzinfo=None):
        super().__init__(year=0, month=1, day=1, hour=0, minute=0, second=0, microsecond=microseconds, nanosecond=nanoseconds, tzinfo=tzinfo)

    @classmethod
    def from_nanoseconds(cls, nanoseconds, tzinfo=None):
        try:
            t = datetime.utcfromtimestamp(nanoseconds / 1e9)  #.fraction is nanoseconds

            if t.tzinfo is not None and tzinfo is None:
                t = t.replace(tzinfo=timezone.utc)

            return cls.fromtimestamp(t.timetuple()[:6], tzinfo)
        except:
            raise ValueError("Invalid nanoseconds")

def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """

    if tz is None and nanoseconds >= 0:
        tz = timezone.utc

    if tz is None:
        return Time.from_nanoseconds(nanoseconds)
    else:
        return Time.from_nanoseconds(nanoseconds, tz)
