import subprocess

def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on Windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """

    def _fix_path(path: str) -> str:
        if os.sep in path:
            return path
        else:
            return os.path.join(os.getcwd(), path)

    fixed_cmd = []
    reused_interp = None

    for arg in cmd:
        if arg == re.findall(r'!([^\s]+)', arg)[0]:
            if reused_interp is not None:
                continue
            reused_interp = arg
            continue
        if arg.strip().startswith("{{") and arg.endswith("}}"):
            arg = arg[2:-2]
            arg = arg.strip()
            continue
        if arg.strip().startswith(".\\") or arg.strip().startswith("/\\"):
            arg = _fix_path(arg)
        elif arg.startswith("/") or arg.startswith("\\"):
            arg = os.path.join(os.getcwd(), arg)
        fixed_cmd.append(arg)

    if reused_interp:
        fixed_cmd.append(reused_interp)

    return tuple(fixed_cmd)
