import time

def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """

    def wrapper(func):
        cache = {}
        last_used = 0

        @wraps(func)
        def inner(*args):
            nonlocal last_used
            key = args

            if key in cache:
                cache[key] = (time.time(), func(*args))
                last_used = max(last_used, time.time())
            elif last_used < maxsize:
                cache[key] = (time.time(), func(*args))
                last_used += 1
                if len(cache) > maxsize:
                    cache.popitem(last=False)

        return inner

    return wrapper
