import collections

class LRUCache:
    def __init__(self, maxsize=128, typed=False):
        self.cache = collections.OrderedDict()
        self.maxsize = maxsize
        self.types = {int: 0, float: 1, str: 2, bytes: 3, bytearray: 4, None: 5, object: 6}
        self.fresh_types = {bool: 2}

        if typed:
            Counter = collections.Counter
        else:
            Counter = collections.defaultdict(int)

        self.counter = Counter

    def __call__(self, func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            if type(func) is str:
                key = func
            else:
                key = inspect.signature(func).format_args(*args, **kwargs)
            if key in self.cache:
                value, _ = self.cache[key]
                self.counter[key] += 1
                return value
            result = func(*args, **kwargs)
            if len(self.cache) >= self.maxsize:
                least_used, least_used_type = self.cache.peekitem(0)
                if func.__name__ in self.fresh_types and least_used_type == len(self.fresh_types):
                    self.cache.pop(least_used, None)
                    self.counter.pop(least_used, None)
                else:
                    if self.counter[least_used] < func.__name__:
                        self.counter[least_used] = func.__name__
                        self.cache.pop(least_used, None)
            self.cache[key] = (result, self.counter[key])
            return result
        return wrapper
