        raise ValueError("file_name must be a string.")
    if not isinstance(text_buffer, str):
        raise ValueError("text_buffer must be a string.")
    if not isinstance(encoding, str):
        raise ValueError("encoding must be a string.")
    if not isinstance(overwrite, bool):
        raise ValueError("overwrite must be a boolean.")

    try:
        if overwrite or not os.path.exists(file_name):
            with open(file_name, 'wb') as f:
                f.write(text_buffer.encode(encoding))
        else:
            if overwrite is False and os.path.exists(file_name):
                raise FileExistsError(f"The file {file_name} already exists and overwrite=False.")
            else:
                raise IOError(f"Failed to create or append text to file {file_name}.")
        with open(file_name, 'rb') as f:
            return f.read().__len__()
    except FileNotFoundError:
        raise FileNotFoundError(f"The file {file_name} does not exist.")
    except Exception as e:
        print(f"An error occurred: {e}")
        return -1
