    if not isinstance(av, InventoryValidator):
        raise ValueError("prior must be an InventoryValidator object")

    if prior.exprev_type != self.exprev_type:
        if self.id:
            raise InvalidInventoryException('Currently in version ' + self.exprev_type + ', made but current status is ' + prior.exprev_type + '.')
        else:
            raise InvalidInventoryException('Made but currently in version ' + prior.exprev_type + '.')

    if self.timestamp > prior.revision_time:
        if self.id:
            raise InvalidInventoryException('Currently in version ' + self.exprev_type + ' but revision time in version ' + prior.revision_time + ' is newer.')
        else:
            raise InvalidInventoryException('Currently in version ' + self.exprev_type + ' but revision time in version ' + prior.revision_time + '.')

    if self.id != prior.exprev_id:
        if self.id:
            extra = ' (id=' + str(self.id) + ')'
        else:
            extra = ''
        raise InvalidInventoryException('Mismatch in prior version ID of exit prior with current version ID ' + str(self.id) + '. ' + extra + '.')

    for i, item in enumerate(self.items):
        if i >= len(prior.items):
            break
        if not equal_items(item, prior.items[i]):
            raise InvalidInventoryException('Items are different at index ' + str(i))

