def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    result = []
    for expr in args:
        if ' ' not in expr:
            result.append(expr)
        else:
            parts = expr.split(' & ')
            left, right = parts[0], parts[1]
            if right.startswith('~'):
                if left.startswith('A'):
                    result.append(left)
                elif right.startswith('~A'):
                    result.append(left)
                else:
                    result.append('A & ' + right[1:])
            else:
                if left.startswith('A'):
                    result.append(right)
                elif right.startswith('A'):
                    result.append(left)
                else:
                    result.append('A & ' + right)
    return result
