def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    if verbose:
        print(f"Running system command: {commands} with arguments {args}")

    try:
        if cwd:
            process = subprocess.Popen(commands, shell=True, cwd=cwd, env=env, stderr=subprocess.STDOUT, stdout=subprocess.PIPE)
        else:
            process = subprocess.Popen(commands, shell=True, env=env, stderr=subprocess.STDOUT, stdout=subprocess.PIPE)

        stdout, stderr = process.communicate()

        if hide_stderr:
            stderr = ''

        if verbose:
            print(f"Command output: {stdout.decode('utf-8').strip()}")
            print(f"Command errored: {stderr.decode('utf-8').strip()}")

        if process.returncode != 0:
