    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if version == '0.0.0':
        return '0.0.1'
    elif version[1:3] == '.0':
        return version[:2] + '0.1'
    elif version[1:4] == '0.0':
        return version[:3] + '1'
    else:
        parts = version.split('.')
        parts = list(map(int, parts))
        parts[-1] += 1
        return '.'.join(map(str, parts))

