def deep_merge_nodes(nodes):
    result = []
    visited = set()

    def merge_values(value1, value2):
        if isinstance(value1, dict) and isinstance(value2, dict):
            return {**value1, **value2}
        elif isinstance(value1, list) and isinstance(value2, list):
            return value1 + value2
        elif value1 != value2:
            return value2
        return value1

    def merge_nodes(node1, node2):
        node1_key = node1[0].tag, node1[0].value
        node2_key = node2[0].tag, node2[0].value

        if node1_key in visited or node2_key in visited:
            return None

        merged_node = (merge_values(node1[0], node2[0]), merge_nodes(node1[1], node2[1]))

        if node1_key in result:
            result[result.index(node1_key)][1].append(merged_node)
        else:
            result.append((node1_key, [merged_node]))

        visited.add(node1_key)
        visited.add(node2_key)

        return merged_node

    for node in nodes:
        merged_node = merge_nodes(node, None)
        if merged_node:
            result.append(merged_node)

    return result
