    parsed_configurations = {}
    logs = []

    for filename in config_filenames:
        # assume configuration file is a JSON file and we're trying to load it
        try:
            with open(filename, 'r') as file:
                config = json.load(file)

            # parse the configuration and add it to the dictionary of parsed configurations
            parsed_configurations[filename] = config

        except FileNotFoundError:
            record = logging.Logger.error(f"Configuration file {filename} not found")
            logs.append(record)

        except json.JSONDecodeError as e:
            record = logging.Logger.error(f"Error decoding configuration file {filename}: {e}")
            logs.append(record)

    return parsed_configurations, logs

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    parsed_configs = {}
    errors = []
    for filename in config_filenames:
        try:
            config = load_configuration_file(filename)
            if overrides:
                config = update_config(config, overrides)
            parsed_configs[filename] = config
        except ConfigurationError as e:
            record = logging.getLogger(__name__).loggingRecord(None, logging.ERROR, None, e.message, None, '[config error: %s]' % filename)
            errors.append(record)
    return parsed_configs, errors

