                elif callable(tzinfos):
                    tzinfos = {tzname: timezone(tzinfo(tzname)) for tzname in tzinfos(timestr)}
                else:
                    tzinfos = dict.fromkeys(tzinfos, timezone(tzinfos))
            except KeyError:
                raise ValueError("invalid timezone")

        try:
            parsed = datetime.strptime(timestr, "%Y-%m-%d %H:%M:%S")
        except ValueError:
            raise ParserError("invalid date/time string")

        if ignoretz:
            parsed = parsed.replace(tzinfo=None)

